### tk_engine/main_server.cpp

```cpp
#include "tk_infer.hpp"
#include <httplib.h>
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>
#include <thread>
#include <cstdlib>

using json = nlohmann::json;

int main(int argc, char* argv[]) {
    std::string model_dir = "/model/zai-org__GLM-4.7-FP8";
    int port = 8000;
    int tp_size = 8;
    float gpu_mem = 0.95f;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "--model-dir" && i + 1 < argc) model_dir = argv[++i];
        if (arg == "--port" && i + 1 < argc) port = std::atoi(argv[++i]);
        if (arg == "--tensor-parallel-size" && i + 1 < argc) tp_size = std::atoi(argv[++i]);
        if (arg == "--gpu-mem-fraction" && i + 1 < argc) gpu_mem = std::atof(argv[++i]);
    }

    TKEngine engine(model_dir, tp_size, gpu_mem);
    engine.load_model();

    httplib::Server svr;

    svr.Post("/v1/chat/completions", [&](const httplib::Request& req, httplib::Response& res) {
        try {
            auto j = json::parse(req.body);

            Request r;
            r.model = j.value("model", "glm-4.7");
            r.id = "req_0";
            if (j.contains("messages") && j["messages"].is_array()) {
                // Simplified prompt extraction
                r.input_ids = {1, 2, 3}; 
            }
            r.max_tokens = j.value("max_tokens", 256);
            r.temperature = j.value("temperature", 0.7f);

            Response response = engine.run_inference(r);

            json choices = json::array();
            choices.push_back({
                {"index", 0},
                {"message", {
                    {"role", "assistant"},
                    {"content", response.text}
                }},
                {"finish_reason", "stop"}
            });

            json resp_json = {
                {"id", response.id},
                {"object", "chat.completion"},
                {"created", 1234567890},
                {"model", response.model},
                {"choices", choices},
                {"usage", {
                    {"prompt_tokens", (int)r.input_ids.size()},
                    {"completion_tokens", (int)response.output_ids.size()},
                    {"total_tokens", (int)(r.input_ids.size() + response.output_ids.size())}
                }}
            };

            res.set_content(resp_json.dump(), "application/json");
        } catch (const std::exception& e) {
            res.status = 500;
            res.set_content(json({{"error", e.what()}}).dump(), "application/json");
        }
    });

    std::cout << "Starting ThunderKittens Server on port " << port << std::endl;
    svr.listen("0.0.0.0", port);

    return 0;
}
